import AppKit
import Foundation

let args = CommandLine.arguments
guard args.count == 3 else { exit(2) }
let role = args[1]
let ready = URL(fileURLWithPath: args[2])
guard role == "allowed" || role == "denied" else { exit(2) }
let app = NSApplication.shared
app.setActivationPolicy(.accessory)
guard let screen = NSScreen.screens.first else { exit(3) }
let visible = screen.visibleFrame
guard visible.width >= 700 && visible.height >= 500 else { exit(4) }
let x = visible.minX + 100
let y = visible.minY + 100
let rect = role == "allowed"
    ? NSRect(x: x, y: y, width: 420, height: 300)
    : NSRect(x: x + 210, y: y + 90, width: 160, height: 140)
let window = NSWindow(contentRect: rect, styleMask: [.borderless], backing: .buffered, defer: false)
window.title = "LingXi Mask Fixture " + role
window.isReleasedWhenClosed = false
window.isOpaque = true
window.hasShadow = false
window.ignoresMouseEvents = true
window.backgroundColor = role == "allowed"
    ? NSColor(calibratedRed: 0.85, green: 0.05, blue: 0.05, alpha: 1.0)
    : NSColor(calibratedRed: 0.05, green: 0.85, blue: 0.05, alpha: 1.0)
window.level = .floating
window.orderFrontRegardless()
DispatchQueue.main.asyncAfter(deadline: .now() + 0.5) {
    let result: [String: Any] = ["pid": ProcessInfo.processInfo.processIdentifier,
        "bundle_id": Bundle.main.bundleIdentifier ?? "", "role": role]
    let data = try! JSONSerialization.data(withJSONObject: result, options: [.sortedKeys])
    try! data.write(to: ready, options: .atomic)
}
app.run()

