#[cfg(not(target_os = "macos"))]
fn main() { eprintln!("macOS required"); std::process::exit(2); }

#[cfg(target_os = "macos")]
#[tokio::main(flavor = "current_thread")]
async fn main() -> Result<(), Box<dyn std::error::Error>> {
    use lingxi_core::host::computer_control::ComputerFrameGeometry;
    let args: Vec<String> = std::env::args().collect();
    if args.len() != 4 { return Err("usage: probe allowed_pid denied_pid allowed_bundle".into()); }
    let allowed_pid: u32 = args[1].parse()?;
    let denied_pid: u32 = args[2].parse()?;
    let bundle = &args[3];
    if !bundle.starts_with("com.lingxi.computer-use.mask-test.") {
        return Err("unexpected fixture bundle".into());
    }
    let backend = platform_macos_computer_control::new_if_supported().ok_or("backend unavailable")?;
    let permissions = backend.query_os_permissions().await?;
    println!("permissions={permissions:?}");
    if !permissions.is_some_and(|(_, recording)| recording) {
        return Err("screen recording unavailable for probe; no request was made".into());
    }
    if backend.screen_locked().await? { return Err("screen locked".into()); }
    let geometry = backend.frame_geometry().await?.ok_or("display geometry unavailable")?;
    let windows = xcap::Window::all()?;
    let mut allowed = None;
    let mut denied = None;
    for (index, window) in windows.iter().enumerate() {
        let pid = match window.pid() { Ok(pid) => pid, Err(_) => continue };
        if pid == allowed_pid || pid == denied_pid {
            let rect = (window.x()?, window.y()?, window.width()?, window.height()?);
            if pid == allowed_pid {
                if allowed.replace((index, rect)).is_some() { return Err("multiple allowed fixture windows".into()); }
            } else if denied.replace((index, rect)).is_some() {
                return Err("multiple denied fixture windows".into());
            }
        }
    }
    let (a_order, a_rect) = allowed.ok_or("allowed fixture window not found")?;
    let (b_order, b_rect) = denied.ok_or("denied fixture window not found")?;
    if b_order >= a_order { return Err("denied fixture is not in front".into()); }
    let bounds = |r: (i32, i32, u32, u32), g: &ComputerFrameGeometry| -> (i64, i64, i64, i64) {
        let x = ((f64::from(r.0) - g.origin_x) * g.scale).round() as i64;
        let y = ((f64::from(r.1) - g.origin_y) * g.scale).round() as i64;
        let w = (f64::from(r.2) * g.scale).round() as i64;
        let h = (f64::from(r.3) * g.scale).round() as i64;
        (x, y, x+w, y+h)
    };
    let a = bounds(a_rect, &geometry);
    let b = bounds(b_rect, &geometry);
    let intersection = (a.0.max(b.0), a.1.max(b.1), a.2.min(b.2), a.3.min(b.3));
    if intersection.2 <= intersection.0 || intersection.3 <= intersection.1 {
        return Err("fixtures do not overlap".into());
    }
    let inside = |p: (i64,i64), r: (i64,i64,i64,i64)| -> bool {
        p.0 >= r.0 && p.0 < r.2 && p.1 >= r.1 && p.1 < r.3
    };
    let candidates = [
        (a.0+(a.2-a.0)/8, a.1+(a.3-a.1)/2),
        (a.0+(a.2-a.0)*7/8, a.1+(a.3-a.1)/2),
        (a.0+(a.2-a.0)/2, a.1+(a.3-a.1)/8),
        (a.0+(a.2-a.0)/2, a.1+(a.3-a.1)*7/8),
    ];
    let visible = candidates.into_iter().find(|&p| !inside(p,b)
        && p.0 >= 0 && p.1 >= 0 && p.0 < i64::from(geometry.pixel_width)
        && p.1 < i64::from(geometry.pixel_height)).ok_or("no visible allowed sample")?;
    let overlap = ((intersection.0+intersection.2)/2, (intersection.1+intersection.3)/2);
    if overlap.0 < 0 || overlap.1 < 0 || overlap.0 >= i64::from(geometry.pixel_width)
        || overlap.1 >= i64::from(geometry.pixel_height) { return Err("overlap outside display".into()); }
    let empty = backend.screenshot_for_apps(&[]).await?;
    let empty_image = image::load_from_memory(&empty.png_bytes)?.to_rgba8();
    let empty_all_black = empty_image.pixels().all(|p| p.0 == [0,0,0,255]);
    let selected = backend.screenshot_for_apps(&[bundle.clone()]).await?;
    let selected_image = image::load_from_memory(&selected.png_bytes)?.to_rgba8();
    if empty_image.dimensions() != selected_image.dimensions() { return Err("capture size changed".into()); }
    let sample = selected_image.get_pixel(visible.0 as u32,visible.1 as u32).0;
    let overlap_pixel = selected_image.get_pixel(overlap.0 as u32,overlap.1 as u32).0;
    let allowed_red = sample[0] > 60 && u16::from(sample[0]) > 2*u16::from(sample[1]);
    let overlap_black = overlap_pixel == [0,0,0,255];
    let mut nonblack = 0usize;
    let mut nonblack_outside = 0usize;
    for (x,y,pixel) in selected_image.enumerate_pixels() {
        if pixel.0 != [0,0,0,255] {
            nonblack += 1;
            if !inside((i64::from(x), i64::from(y)),a) { nonblack_outside += 1; }
        }
    }
    println!("dimensions={}x{}",selected.width,selected.height);
    println!("empty_all_black={empty_all_black} allowed_red={allowed_red} denied_overlap_black={overlap_black} nonblack_pixels={nonblack} nonblack_outside_allowed={nonblack_outside}");
    if !empty_all_black || !allowed_red || !overlap_black || nonblack == 0 || nonblack_outside != 0 {
        return Err("mask assertion failed; no image was persisted".into());
    }
    println!("result=pass; no image persisted");
    Ok(())
}
